import {updateCelebrationState} from './repository';
const setupCarousel = (host) => {
    const root = host.querySelector('[data-region="learning-celebration"]');
    if (!root || root.dataset.initialised === '1') {
        return null;
    }
    root.dataset.initialised = '1';

    const slides = Array.from(root.querySelectorAll('[data-slide]'));
    const dots = Array.from(root.querySelectorAll('[data-action="goto"]'));
    const previous = root.querySelector('[data-action="previous"]');
    const next = root.querySelector('[data-action="next"]');
    const restart = root.querySelector('[data-action="restart"]');
    const finish = root.querySelector('[data-action="finish"]');
    const counter = root.querySelector('[data-region="counter"]');
    let current = 0;

    const show = (index) => {
        if (!slides.length) {
            return;
        }
        current = Math.max(0, Math.min(index, slides.length - 1));

        slides.forEach((slide, slideIndex) => {
            const active = slideIndex === current;
            slide.hidden = !active;
            slide.setAttribute('aria-hidden', active ? 'false' : 'true');
        });

        dots.forEach((dot, dotIndex) => {
            const active = dotIndex === current;
            dot.classList.toggle('is-active', active);
            dot.setAttribute('aria-current', active ? 'step' : 'false');
        });

        const isLast = current === slides.length - 1;
        if (previous) {
            previous.disabled = current === 0;
        }
        if (next) {
            next.hidden = isLast;
        }
        if (restart) {
            restart.hidden = !isLast;
        }
        if (finish) {
            finish.hidden = !isLast;
        }
        if (counter) {
            counter.textContent = `${current + 1} / ${slides.length}`;
        }
    };

    previous?.addEventListener('click', () => show(current - 1));
    next?.addEventListener('click', () => show(current + 1));
    restart?.addEventListener('click', () => show(0));

    dots.forEach((dot) => {
        dot.addEventListener('click', () => {
            show(Number.parseInt(dot.dataset.targetSlide, 10) || 0);
        });
    });

    root.addEventListener('keydown', (event) => {
        if (event.key === 'ArrowLeft') {
            event.preventDefault();
            show(current - 1);
        } else if (event.key === 'ArrowRight') {
            event.preventDefault();
            show(current + 1);
        } else if (event.key === 'Home') {
            event.preventDefault();
            show(0);
        } else if (event.key === 'End') {
            event.preventDefault();
            show(slides.length - 1);
        }
    });

    show(0);
    return {root, finish};
};

/**
 * Initialise a static preview/replay carousel.
 *
 * @param {String} rootId Root element id.
 */
export const init = (rootId) => {
    const host = document.getElementById(rootId);
    if (!host) {
        return;
    }
    setupCarousel(host);
};

/**
 * Initialise the automatic modal overlay.
 *
 * @param {String} rootId Root element id.
 * @param {Number} celebrationYear Observed birthday year.
 * @param {Boolean} motionEnabled Whether plugin-authored motion is enabled.
 */
export const initOverlay = (rootId, celebrationYear, motionEnabled = true) => {
    const host = document.getElementById(rootId);
    if (!host) {
        return;
    }

    const carousel = setupCarousel(host);
    if (!carousel) {
        return;
    }

    const dialog = host.querySelector('[data-region="overlay-dialog"]');
    const notNow = host.querySelector('[data-action="notnow"]');
    const finish = host.querySelector('[data-action="finish"]');
    const status = host.querySelector('[data-region="action-status"]');
    const previouslyFocused = document.activeElement;
    let closing = false;
    const reducedMotion = !motionEnabled || window.matchMedia('(prefers-reduced-motion: reduce)').matches;

    const postAction = async(action) => {
        const data = await updateCelebrationState(action, celebrationYear);
        if (!data || data.success !== true) {
            throw new Error('Learning Celebration action did not complete.');
        }
    };

    const close = () => {
        if (closing) {
            return;
        }
        closing = true;
        host.dataset.overlayState = 'closing';
        document.body.classList.remove('lc-celebration-open');
        window.setTimeout(() => {
            host.remove();
            if (previouslyFocused instanceof HTMLElement && document.contains(previouslyFocused)) {
                previouslyFocused.focus();
            }
        }, reducedMotion ? 0 : 180);
    };

    const runAction = async(action, button) => {
        if (button) {
            button.disabled = true;
        }
        if (status) {
            status.hidden = true;
        }
        try {
            await postAction(action);
            close();
        } catch (error) {
            if (status) {
                status.hidden = false;
            }
            if (button) {
                button.disabled = false;
            }
            window.console.error(error);
        }
    };

    notNow?.addEventListener('click', () => runAction('snooze', notNow));
    finish?.addEventListener('click', () => runAction('complete', finish));

    const focusableSelector = [
        'button:not([disabled]):not([hidden])',
        'a[href]',
        'input:not([disabled])',
        'select:not([disabled])',
        'textarea:not([disabled])',
        '[tabindex]:not([tabindex="-1"])',
    ].join(', ');
    const getFocusable = () => Array.from(host.querySelectorAll(focusableSelector))
        .filter((element) => !element.hidden && element.getClientRects().length > 0);

    host.addEventListener('keydown', (event) => {
        if (event.key === 'Escape') {
            event.preventDefault();
            notNow?.click();
            return;
        }

        if (event.key !== 'Tab') {
            return;
        }

        const focusable = getFocusable();
        if (!focusable.length) {
            event.preventDefault();
            dialog?.focus();
            return;
        }

        const first = focusable[0];
        const last = focusable[focusable.length - 1];
        if (event.shiftKey && document.activeElement === first) {
            event.preventDefault();
            last.focus();
        } else if (!event.shiftKey && document.activeElement === last) {
            event.preventDefault();
            first.focus();
        }
    });

    document.body.classList.add('lc-celebration-open');
    window.setTimeout(() => {
        host.dataset.overlayState = 'open';
        dialog?.focus();
    }, reducedMotion ? 0 : 350);
};
